// Builds data.js for the landing page from real artefacts only:
//  - room plans: IWER room captures (packages/core/test/fixtures/iwer-*.json)
//    with puzzle 10 generated by the core package in each room;
//  - metrics: the e2e / perf / test reports in e2e-out/ (missing ones are omitted).
// Usage: node scripts/build-data.mjs
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../../..');
const tmp = join(here, '.tmp');
mkdirSync(tmp, { recursive: true });
const esbuild = join(root, 'packages/app/node_modules/esbuild/bin/esbuild');
execFileSync(esbuild, [join(root, 'packages/core/src/index.ts'), '--bundle', '--format=esm', `--outfile=${join(tmp, 'core.mjs')}`, '--log-level=warning']);
const core = await import(pathToFileURL(join(tmp, 'core.mjs')).href);

const ROOMS = [
  ['sunlit_living_room', 'Sunlit living room'],
  ['home_office', 'Home office'],
  ['kitchen', 'Kitchen'],
];
const plans = [];
for (const [env, label] of ROOMS) {
  const f = join(root, `packages/core/test/fixtures/iwer-${env}.json`);
  if (!existsSync(f)) continue;
  const input = JSON.parse(readFileSync(f, 'utf8'));
  const room = core.buildRoom(input.planes, { head: input.head, forward: input.forward, meshes: input.meshes });
  const p = core.generatePuzzle(room, core.PUZZLES[9]);
  const path = core.replay(p.world, p.start, p.solution);
  const xz = (v) => [v[0], v[2]];
  const box = (b) => ({ min: xz(b.min), max: xz(b.max) });
  plans.push({
    env,
    label,
    min: xz(room.min),
    size: [room.max[0] - room.min[0], room.max[2] - room.min[2]],
    solids: room.solids.map(box),
    blocks: p.blocks.map(box),
    start: xz(p.start),
    goal: xz(p.goal),
    path: path.map(xz),
    head: xz(room.head),
    par: p.par,
    solution: p.solution.map((d) => core.DIR_NAMES[d].toUpperCase()).join(' '),
  });
}

const out = join(root, 'e2e-out');
const read = (name) => {
  const f = join(out, name);
  return existsSync(f) ? JSON.parse(readFileSync(f, 'utf8')) : null;
};
const metrics = [];
const quest = read('hands-quest.json');
const glasses = read('hands-glasses.json');
const perf = read('perf.json');
const agree = read('solver-havok-agreement.json');
const det = read('determinism.json');
if (quest) metrics.push({ label: 'QUEST 3 HANDS E2E', value: `${quest.passed}/${quest.total}`, unit: 'checks' });
if (glasses) metrics.push({ label: 'GLASSES GAZE E2E', value: `${glasses.passed}/${glasses.total}`, unit: 'checks' });
if (agree) metrics.push({ label: 'SOLVER = HAVOK', value: `${agree.won}/${agree.total}`, unit: `puzzles, ${agree.rooms.length} rooms` });
if (perf) metrics.push({ label: 'EMULATOR CPU P95', value: perf.cpuMs.p95.toFixed(2), unit: 'ms / frame' });
if (perf) metrics.push({ label: 'DRAW CALLS (MAX)', value: String(perf.drawCalls.max), unit: 'per view' });
if (det) metrics.push({ label: 'REPLAYS IDENTICAL', value: `${det.identical ? det.runs : 0}/${det.runs}`, unit: 'runs' });
if (quest) metrics.push({ label: 'PINCHES TO FIRST WHOA', value: String(quest.handActionsToWhoa), unit: 'pinch' });

writeFileSync(join(here, '..', 'data.js'), `// Generated by scripts/build-data.mjs from real test artefacts. Do not edit by hand.\nwindow.SAKASA_DATA = ${JSON.stringify({ plans, metrics }, null, 1)};\n`);
console.log(`data.js: ${plans.length} plans, ${metrics.length} metrics`);
